#include <iostream>
#include <utility>
template<typename T>
void printValue(T&& value) {
  std::cout << value << " ";
  std::cout << (std::is_lvalue_reference<T>::value ? "(lvalue)" : "(rvalue)") << std::endl;
}
template<typename... Args>
void perfectForward(Args&&... args) {
  (printValue(std::forward<Args>(args)), ...);
}
int main() {
  int x = 10;
  perfectForward(x, 20, std::string("hello"));  //Testing
  return 0;
}
